package com.student.studentanalyzer.controller; import com.student.studentanalyzer.entity.RoleSkillRequirement; import com.student.studentanalyzer.repository.RoleSkillRequirementRepository; import org.springframework.web.bind.annotation.*; import java.util.List; @RestController @RequestMapping("/api/role-requirements") @CrossOrigin(origins = "*") public class RoleSkillRequirementController { private final RoleSkillRequirementRepository requirementRepository; public RoleSkillRequirementController( RoleSkillRequirementRepository requirementRepository) { this.requirementRepository = requirementRepository; } @GetMapping("/{roleName}") public List<RoleSkillRequirement> getRequirements( @PathVariable String roleName) { return requirementRepository.findByRoleNameIgnoreCase(roleName); } }